class KeyedQueue {
  tails = new Map;
  run(key, work) {
    const result = (this.tails.get(key) ?? Promise.resolve()).then(work, work);
    const tail = result.then(() => {
      return;
    }, () => {
      return;
    });
    this.tails.set(key, tail);
    tail.then(() => {
      if (this.tails.get(key) === tail)
        this.tails.delete(key);
    });
    return result;
  }
}

