  label: "Regions (US states, DC and the national baseline)",
  source: { dataPack: "modern-us", file: "us/regions.json", sourceSchema: "lre-data-src/us/regions/v1", reflectsPeriod: "2025-2026 (point-in-time, mid-2025 to early-2026 values)", approximate: true, basis: { summary: "Rounded, approximate state-level figures compiled from well-known public statistics as recalled; not queried live. Intended as plausible defaults, not as authoritative statistics.", state_income_tax_effective_pct: "Approximate effective state income tax as a percent of gross wages for a single filer earning about $60,000 (a middle-income band), after the state standard deduction/exemptions; derived from published 2025 state brackets (Tax Foundation / state revenue departments). Rounded to 0.1. Excludes local income taxes (see local_income_tax_pct_typical) and payroll-type state levies such as CA SDI.", sales_tax_combined_avg_pct: "Tax Foundation 2025 combined state plus population-weighted average local sales tax rate; rounded to 0.01. Hawaii and Alaska values are approximations of the GET / local-only rate.", property_tax_effective_pct: "Approximate effective property tax on owner-occupied homes: median real-estate taxes paid as a percent of median home value (US Census ACS 1-year estimates, as compiled by the Tax Foundation), rounded to 0.01.", cost_of_living_multiplier: "US = 1.00. Approximate from BEA Regional Price Parities (all items, 2022-2023 vintage) smoothed to 2025; rounded to 0.01.", median_rent_cents_per_month: "Approximate asking-rent medians for 1BR and 2BR units, a blend of Zumper, Apartment List and HUD FY2025 Fair Market Rent state patterns, rounded to $10. 1BR is the anchor; 2BR is derived as 1BR times a regional ratio (Northeast 1.22, Midwest 1.27, South 1.27, West 1.24; DC uses South) rounded to $10. Statewide medians hide large metro-vs-rural spread.", residential_electricity_cents_per_kwh: "EIA Electric Power Monthly, average residential retail price by state, 2024 annual / 2025 year-to-date, rounded to 0.5 cent. Decimal value in cents (not dollars) per kWh. US average is about 17 cents.", minimum_wage_cents_per_hour: "Effective statutory floor in 2025 for non-tipped adult workers: the higher of the state rate and the federal $7.25. Where rates vary by locality or employer size (NY, OR, MN) the statewide/largest-area figure is used.", suta_wage_base_cents: "State unemployment (SUTA) taxable wage base for 2025, a year per employee per employer, as published by the state workforce agencies (and compiled by payroll providers), rounded to the dollar.", suta_new_employer_pct: "The state's 2025 contribution rate for a new employer (no experience rating yet), employer share only; where it varies by industry the general (non-construction) rate is used, rounded to 0.01 (0.001 where the state publishes more).", futa_credit_reduction_pct: "The FUTA credit reduction a state whose unemployment fund owes federal loans carries for 2025 (US DOL): California 1.2. Absent where there is none.", tipped_minimum_wage_cents_per_hour: "Effective 2025 cash wage floor for tipped workers where the state sets one above the federal $2.13: Michigan's $4.74 (from 21 Feb 2025; $5.49 from 1 Jan 2026), Ohio's half of its minimum, and the full minimum in the states that allow no tip credit (AK, CA, MN, MT, NV, OR, WA). Absent where the federal floor applies, or where this table doesn't yet record the state's." } },
  columns: {
    name: { type: "text" },
    abbr: { type: "text" },
    scope: { type: "enum", values: ["national", "state", "district"], doc: "`national` is the single baseline row `us` (multiplier 1.00); the state-only columns are absent on it." },
    census_region: { type: "enum", values: ["Midwest", "Northeast", "South", "West"], optional: true },
    census_division: { type: "enum", values: ["East North Central", "East South Central", "Middle Atlantic", "Mountain", "New England", "Pacific", "South Atlantic", "West North Central", "West South Central"], optional: true },
    time_zones: { type: "list", of: "text", doc: "IANA ids, primary first.", optional: true },
    observes_dst: { type: "bool", optional: true },
    state_income_tax_effective_pct: { type: "number", unit: "pct", doc: "Single filer at about $60,000, after the state standard deduction; excludes local and payroll levies.", optional: true },
    local_income_tax_pct_typical: { type: "number", unit: "pct", optional: true },
    sales_tax_combined_avg_pct: { type: "number", unit: "pct", doc: "State plus average local rate." },
    property_tax_effective_pct: { type: "number", unit: "pct", doc: "Effective property tax on owner-occupied homes, a year, percent of value.", optional: true },
    suta_wage_base_cents: { type: "int", unit: "cents", doc: "State unemployment tax's wage base: the wages a year, per employee per employer, SUTA is paid on." },
    suta_new_employer_pct: { type: "number", unit: "pct", doc: "State unemployment tax rate of a new employer (employer share, general industry)." },
    futa_credit_reduction_pct: { type: "number", unit: "pct", doc: "Reduction of the 5.4% FUTA credit for wages paid in a credit-reduction state; absent where there is none.", optional: true },
    cost_of_living_multiplier: { type: "number", unit: "multiplier", doc: "US = 1.00. Applied by the economy pack at pricing time, never baked into rows." },
    median_rent_1br_cents_per_month: { type: "int", unit: "cents_per_month" },
    median_rent_2br_cents_per_month: { type: "int", unit: "cents_per_month" },
    residential_electricity_cents_per_kwh: { type: "number", unit: "cents_per_kwh", doc: "Decimal cents." },
    minimum_wage_cents_per_h: { type: "int", unit: "cents_per_h", doc: "Effective 2025 floor, the higher of state and federal." },
    tipped_minimum_wage_cents_per_h: { type: "int", unit: "cents_per_h", doc: "Effective 2025 cash wage floor for tipped work where the state sets one above the federal floor; absent where the federal floor applies.", optional: true },
    notes: { type: "text", optional: true }
  },
